export function bulkExcel(opts) {
    if (opts.fieldMappings.length === 0)
        throw new Error("bulkExcel requires at least one fieldMapping.");
    assertFileReaderReference(opts.documentModel, "bulkExcel");
    return {
        key: "bulkExcel",
        config: {
            attachmentId: serializeValueOrRef(opts.attachmentId),
            documentModelId: opts.documentModel,
            aspectId: opts.app,
            aspectType: opts.aspectType,
            ...(opts.strict !== undefined ? { strict: opts.strict } : {}),
            fieldMappings: opts.fieldMappings.map((m) => ({
                aspectFieldId: m.field,
                fieldMappingInput: m.source.type === "documentModelField"
                    ? { documentModelFieldId: m.source.field }
                    : { valueReference: serializeValueOrRef(m.source.value) },
            })),
        },
    };
}
